import React, { useContext } from 'react';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import { AuthProvider, AuthContext } from './context/AuthContext';
import ProtectedRoute from './components/ProtectedRoute';
import Home from './pages/Home';
import Catalog from './pages/Catalog';
import ProductDetail from './pages/ProductDetail';
import Login from './pages/Login';
import Register from './pages/Register';
import Dashboard from './pages/Dashboard';
import Profile from './pages/Profile';

const Navigation = () => {
  const { user, logout } = useContext(AuthContext);

  return (
    <header style={{ 
      background: '#ffffff', 
      borderBottom: '1px solid #eaeaea', 
      boxShadow: '0 2px 10px rgba(0,0,0,0.03)',
      position: 'sticky',
      top: 0,
      zIndex: 100
    }}>
      <div style={{ 
        maxWidth: '1200px', 
        margin: '0 auto', 
        padding: '16px 20px', 
        display: 'flex', 
        alignItems: 'center', 
        justifyContent: 'space-between' 
      }}>
        {/* Логотип и главная навигация */}
        <div style={{ display: 'flex', gap: '30px', alignItems: 'center' }}>
          <Link to="/" style={{ 
            fontWeight: '800', 
            fontSize: '22px', 
            color: '#1a1a1a', 
            textDecoration: 'none',
            display: 'flex',
            alignItems: 'center',
            gap: '8px'
          }}>
            <span style={{ 
              background: '#F59E0B', 
              color: '#1a1a1a', 
              padding: '4px 10px', 
              borderRadius: '8px', 
              fontSize: '18px' 
            }}>
              Geo
            </span>
            <span>Shop</span>
          </Link>

          <nav style={{ display: 'flex', gap: '20px' }}>
            <Link to="/" style={{ color: '#444', textDecoration: 'none', fontWeight: '600', fontSize: '15px' }}>
              Главная
            </Link>
            <Link to="/catalog" style={{ color: '#444', textDecoration: 'none', fontWeight: '600', fontSize: '15px' }}>
              Каталог
            </Link>
          </nav>
        </div>

        {/* Пользовательский блок */}
        <div style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
          {user ? (
            <>
              <Link to="/dashboard" style={{ color: '#1a1a1a', textDecoration: 'none', fontWeight: '600', fontSize: '15px' }}>
                Панель управления
              </Link>
              <Link to="/profile" style={{ 
                background: '#fdfbf7', 
                border: '1px solid #faedcd', 
                padding: '8px 16px', 
                borderRadius: '20px', 
                color: '#D97706', 
                textDecoration: 'none', 
                fontWeight: '600',
                fontSize: '14px' 
              }}>
                👤 {user.username}
              </Link>
              <button 
                onClick={logout} 
                style={{ 
                  background: '#fee2e2', 
                  color: '#dc2626', 
                  border: 'none', 
